"""Strict input schema for the EV hypothesis playground."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Annotated, Literal

import yaml
from pydantic import BaseModel, ConfigDict, Field, TypeAdapter, field_validator, model_validator


class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)


FinitePositive = Annotated[float, Field(gt=0, allow_inf_nan=False)]
FiniteFraction = Annotated[float, Field(ge=0, le=1, allow_inf_nan=False)]


class CompositionConfig(StrictModel):
    mode: Literal["preserve_city", "preserve_energy"] = "preserve_city"
    residential: FiniteFraction | None = None
    commercial: FiniteFraction | None = None
    industrial: FiniteFraction | None = None

    @model_validator(mode="after")
    def weights_sum_to_one(self) -> "CompositionConfig":
        weights = (self.residential, self.commercial, self.industrial)
        if any(value is not None for value in weights):
            if any(value is None for value in weights) or abs(sum(weights) - 1.0) > 1e-9:
                raise ValueError("composition weights must all be supplied and sum to 1")
        return self


class DemandConfig(StrictModel):
    scope: Literal["city_total", "active_sources"] = "city_total"
    monthly_energy: FinitePositive = 95_636.0
    unit: Literal["kWh", "MWh"] = "MWh"
    month: Annotated[int, Field(ge=1, le=12)] = 1
    days_per_month: Annotated[int, Field(ge=1, le=31)] = 30
    days: Annotated[int, Field(ge=1, le=31)] = 1
    annual_growth_rate: FiniteFraction = 0.03
    years_ahead: Annotated[int, Field(ge=0, le=100)] = 0
    variation: Literal["base", "lower", "upper"] = "base"
    composition: CompositionConfig = Field(default_factory=CompositionConfig)


class LocationMix(StrictModel):
    residential: FiniteFraction = 0.7
    workplace: FiniteFraction = 0.2
    public: FiniteFraction = 0.1

    @model_validator(mode="after")
    def weights_sum_to_one(self) -> "LocationMix":
        if abs(self.residential + self.workplace + self.public - 1.0) > 1e-9:
            raise ValueError("location_mix weights must sum to 1")
        return self


class FleetConfig(StrictModel):
    fleet_size: Annotated[int, Field(ge=0, le=1_000_000)] = 100
    charger_kw: FinitePositive = 7.4
    energy_kwh: FinitePositive = 14.0
    efficiency: Annotated[float, Field(gt=0, le=1, allow_inf_nan=False)] = 0.9
    location_mix: LocationMix = Field(default_factory=LocationMix)


HardMetric = Literal[
    "min_voltage_pu", "max_line_loading_percent", "max_transformer_loading_percent",
    "unmet_energy_kwh", "nonconverged_steps", "overload_steps",
]


class HardAssertion(StrictModel):
    type: Literal["hard"] = "hard"
    metric: HardMetric
    operator: Literal["le", "ge"]
    value: Annotated[float, Field(allow_inf_nan=False)]


class PairedAssertion(StrictModel):
    type: Literal["paired"] = "paired"
    metric: Literal["peak_demand_kw"]
    reduction_fraction: FiniteFraction
    control: str = Field(min_length=1)
    candidate: str = Field(min_length=1)


Assertion = HardAssertion | PairedAssertion


class Limits(StrictModel):
    min_voltage_pu: Annotated[float, Field(gt=0, le=2, allow_inf_nan=False)] = 0.95
    max_voltage_pu: Annotated[float, Field(gt=0, le=2, allow_inf_nan=False)] = 1.05
    max_loading_percent: FinitePositive = 100.0

    @model_validator(mode="after")
    def voltage_order(self) -> "Limits":
        if self.min_voltage_pu >= self.max_voltage_pu:
            raise ValueError("min_voltage_pu must be less than max_voltage_pu")
        return self


class Experiment(StrictModel):
    schema_version: Literal[1] = 1
    name: str = Field(min_length=1)
    hypothesis: str = Field(min_length=1)
    metric_boundary: Literal["city_total", "grid_asset", "departure"] = "city_total"
    observation_contract: Literal["current_state"] = "current_state"
    case_origin: Literal["manual", "llm", "random", "ga"] = "manual"
    assumptions: list[str] = Field(default_factory=lambda: [
        "Demand shapes are user-supplied seasonal hourly profiles.",
        "Land-use and charging-window archetypes are explicit planning assumptions.",
    ])
    demand: DemandConfig = Field(default_factory=DemandConfig)
    fleet: FleetConfig = Field(default_factory=FleetConfig)
    strategies: list[Literal["immediate", "fixed_delay", "randomized_delay", "capacity_aware"]] = Field(
        default_factory=lambda: ["immediate", "fixed_delay", "randomized_delay", "capacity_aware"]
    )
    seeds: list[Annotated[int, Field(ge=0, le=2**32 - 1)]] = Field(default_factory=lambda: [1])
    fleet_sizes: list[Annotated[int, Field(ge=0, le=1_000_000)]] | None = None
    limits: Limits = Field(default_factory=Limits)
    assertions: list[Assertion] = Field(default_factory=list)
    max_cases: Annotated[int, Field(ge=1, le=10_000)] = 100
    max_runtime_seconds: Annotated[float, Field(gt=0, le=86_400, allow_inf_nan=False)] = 600.0
    stress_first: bool = True
    stop_on_violation: bool = True
    fixed_start_hour: Annotated[int, Field(ge=0, le=23)] = 23

    @field_validator("strategies", "seeds")
    @classmethod
    def nonempty_unique(cls, value: list[object]) -> list[object]:
        if not value:
            raise ValueError("list must not be empty")
        if len(value) != len(set(value)):
            raise ValueError("list entries must be unique")
        return value

    @field_validator("assumptions")
    @classmethod
    def assumptions_are_labeled(cls, value: list[str]) -> list[str]:
        if not value or any(not item.strip() for item in value):
            raise ValueError("assumptions must contain nonempty labeled entries")
        return value

    @field_validator("fleet_sizes")
    @classmethod
    def unique_sweep(cls, value: list[int] | None) -> list[int] | None:
        if value is not None and (not value or len(value) != len(set(value))):
            raise ValueError("fleet_sizes must be nonempty and unique when supplied")
        return value

    @model_validator(mode="after")
    def paired_assertions_reference_cases(self) -> "Experiment":
        for assertion in self.assertions:
            if isinstance(assertion, PairedAssertion):
                if assertion.control == assertion.candidate:
                    raise ValueError("paired assertion control and candidate must differ")
                if assertion.control not in self.strategies or assertion.candidate not in self.strategies:
                    raise ValueError("paired assertion control and candidate must be selected strategies")
        return self


def load_experiment(source: Mapping[str, object] | str) -> Experiment:
    """Validate a mapping or a YAML document as an :class:`Experiment`."""
    if isinstance(source, str):
        data = yaml.safe_load(source)
    elif isinstance(source, Mapping):
        data = dict(source)
    else:
        raise TypeError("experiment source must be a mapping or YAML string")
    if not isinstance(data, dict):
        raise ValueError("experiment YAML must contain a mapping at its root")
    return Experiment.model_validate(data)


ASSERTION_ADAPTER = TypeAdapter(Assertion)

service.py:
"""Persistent, immutable experiment definitions and restartable local jobs."""
from __future__ import annotations

import hashlib
import itertools
import json
import os
from pathlib import Path
import subprocess
import sys
import time
import uuid
from datetime import datetime, timezone
from typing import Any

from mvgrid.paths import REPOSITORY_ROOT, NOVI_SAD_GENERATED_DIR
from .schema import Experiment, load_experiment


def canonical(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(f".{uuid.uuid4().hex}.tmp")
    temporary.write_text(canonical(value), encoding="utf-8")
    # Windows readers/antivirus may briefly hold a destination without delete sharing.
    for attempt in range(40):
        try:
            os.replace(temporary, path)
            break
        except PermissionError:
            if attempt == 39:
                temporary.unlink(missing_ok=True)
                raise
            time.sleep(.025)


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def implementation_fingerprint() -> dict:
    import importlib.metadata
    files = {p.name: hashlib.sha256(p.read_bytes()).hexdigest()
             for p in sorted(Path(__file__).parent.glob("*.py"))}
    inputs = {}
    for name in ("novi_sad_synthetic_transformers.csv", "novi_sad_synthetic_feeder_assignments.csv", "novi_sad_seeded_substations.json"):
        p = NOVI_SAD_GENERATED_DIR / name
        inputs[name] = hashlib.sha256(p.read_bytes()).hexdigest()
    topology = REPOSITORY_ROOT / "data/novi_sad/playground/reduced_network.json"
    inputs["reduced_network.json"] = hashlib.sha256(topology.read_bytes()).hexdigest()
    versions = {name: importlib.metadata.version(name) for name in ("pandapower", "numpy", "pandas", "pydantic", "mcp")}
    return {"source_hashes": files, "input_hashes": inputs, "dependencies": versions}


def cases_for(config: dict) -> list[dict]:
    sizes = config.get("fleet_sizes") or [config["fleet"]["fleet_size"]]
    return [{"case_id": f"case-{i:04d}", "strategy": strategy, "seed": seed, "fleet_size": size}
            for i, (size, seed, strategy) in enumerate(itertools.product(sizes, config["seeds"], config["strategies"]))]


class Service:
    def __init__(self, root: str | Path | None = None):
        self.root = Path(root or os.environ.get("EV_PLAYGROUND_HOME", REPOSITORY_ROOT / "artifacts" / "playground" / "runtime")).resolve()

    def _path(self, category: str, identifier: str) -> Path:
        if not identifier or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789-" for c in identifier):
            raise ValueError("Invalid identifier; use an ID returned by the service.")
        return self.root / category / identifier

    def catalog(self) -> dict:
        return {"schema": Experiment.model_json_schema(), "example": Experiment(name="Evening charging comparison", hypothesis="Staggering charging reduces the synchronized evening peak").model_dump(mode="json"),
                "strategies": ["immediate", "fixed_delay", "randomized_delay", "capacity_aware"],
                "backend": "reduced_pandapower", "fidelity": "Balanced equivalent MV network; synthetic blocks, not an as-built model",
                "metrics": ["peak_demand_kw", "max_line_loading_percent", "max_transformer_loading_percent", "min_voltage_pu", "unmet_energy_kwh", "nonconverged_steps", "overload_steps"],
                "assumptions": ["15-minute average demand; no sub-interval transients", "Synthetic EV sessions and block allocation", "Selected detailed checks are optional", "Configured limit stop is an experiment stop, not a physical protection-trip model", "NS1, NS6 and FUT are excluded by user instruction; city-total demand is scaled by retained reference demand share", "No harmonics or phase imbalance model"]}

    def validate_experiment(self, definition: dict | str) -> dict:
        config = load_experiment(definition).model_dump(mode="json")
        cases = cases_for(config)
        if len(cases) > config["max_cases"]:
            raise ValueError(f"Expanded {len(cases)} cases exceeds max_cases={config['max_cases']}")
        replay_events = sum(config["demand"]["days"] * size for size in set(c["fleet_size"] for c in cases)) * len(config["seeds"])
        if replay_events > 250_000:
            raise ValueError("Expanded session replay exceeds the MVP limit of 250,000 events. Reduce fleet sizes, days or seeds.")
        return {"valid": True, "definition": config, "cases": cases,
                "estimated_power_flows": len(cases) * (config["demand"]["days"] * 96 + (36 if any(c['fleet_size'] for c in cases) else 0)),
                "runtime_note": "Upper-bound interval count includes up to 9 hours overnight completion, excludes control retries. Measure runtime on this machine."}

    def save_experiment(self, definition: dict | str) -> dict:
        config = self.validate_experiment(definition)["definition"]
        identifier = "exp-" + digest(config)[:20]
        path = self._path("experiments", identifier).with_suffix(".json")
        record = {"experiment_id": identifier, "definition": config}
        if not path.exists():
            write_json(path, record)
        return record

    def add_cases(self, experiment_id: str, patch: dict) -> dict:
        config = self.get_experiment(experiment_id)["definition"]
        # A patch is a complete replacement for each supplied top-level field.
        config.update(patch)
        return self.save_experiment(config)

    def get_experiment(self, experiment_id: str) -> dict:
        return read_json(self._path("experiments", experiment_id).with_suffix(".json"))

    def list_experiments(self) -> list[dict]:
        return [read_json(p) for p in sorted((self.root / "experiments").glob("*.json"))]

    def list_runs(self) -> list[dict]:
        return [self.get_run(p.parent.name) for p in sorted((self.root / "runs").glob("*/state.json"), reverse=True)]

    def start_run(self, experiment_id: str, resume_run_id: str | None = None) -> dict:
        self.root.mkdir(parents=True, exist_ok=True)
        lock = self.root / "worker.lock"
        try:
            fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            active = lock.read_text(encoding="utf-8").strip()
            if not active:
                raise ValueError("Another run is being registered; retry shortly.")
            if self.get_run(active)["status"] in ("running", "starting"):
                raise ValueError(f"One worker is active: {active}. Wait or cancel it first.")
            lock.unlink(missing_ok=True)
            fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        try:
            if resume_run_id:
                run_id = resume_run_id
                folder = self._path("runs", run_id)
                state = self.get_run(run_id)
                if state["experiment_id"] != experiment_id or state["status"] not in ("cancelled", "budget_exceeded", "interrupted", "failed"):
                    raise ValueError("Only an interrupted, cancelled, failed or budget-limited matching run can resume.")
                manifest = read_json(folder / "manifest.json")
                if manifest["fingerprint"] != implementation_fingerprint():
                    raise ValueError("Code, dependencies or reference inputs changed; start a new run instead of mixing evidence.")
                if hashlib.sha256((folder / "network.json").read_bytes()).hexdigest() != manifest["network_hash"] or any(digest(replay)!=manifest["replay_hashes"][key] for key,replay in manifest["replays"].items()):
                    raise ValueError("Frozen network or replay changed; cannot resume altered evidence.")
                (folder / "cancel").unlink(missing_ok=True)
            else:
                run_id = "run-" + uuid.uuid4().hex[:16]
                folder = self._path("runs", run_id)
                folder.mkdir(parents=True)
                state = {"run_id": run_id, "experiment_id": experiment_id, "status": "starting", "completed_cases": 0,
                         "created_at": datetime.now(timezone.utc).isoformat(), "verdict": "incomplete"}
                write_json(folder / "state.json", state)
            os.write(fd, run_id.encode())
            os.close(fd)
            fd = None
            state.update(status="starting", verdict="incomplete", pid=None)
            write_json(folder / "state.json", state)
            env = dict(os.environ, PYTHONPATH=str(REPOSITORY_ROOT / "src"))
            log = open(folder / "worker.log", "a", encoding="utf-8")
            try:
                process = subprocess.Popen([sys.executable, "-m", "mvgrid.novi_sad.playground.worker", str(self.root), run_id],
                    cwd=str(REPOSITORY_ROOT), env=env, stdout=log, stderr=log,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0) | getattr(subprocess, "CREATE_BREAKAWAY_FROM_JOB", 0))
            finally:
                log.close()
            # Worker waits for pid registration to avoid competing state writes.
            state["pid"] = process.pid
            write_json(folder / "state.json", state)
            return state
        except Exception:
            if fd is not None:
                os.close(fd)
            lock.unlink(missing_ok=True)
            raise

    def get_run(self, run_id: str) -> dict:
        folder = self._path("runs", run_id)
        state = read_json(folder / "state.json")
        pid = state.get("pid")
        if state["status"] in ("running", "starting") and pid:
            import psutil
            if not psutil.pid_exists(pid):
                state.update(status="interrupted", verdict="incomplete")
                write_json(folder / "state.json", state)
        elif state["status"] == "starting" and not pid:
            if time.time() - (folder / "state.json").stat().st_mtime > 30:
                state.update(status="interrupted", verdict="incomplete")
                write_json(folder / "state.json", state)
        return state

    def cancel_run(self, run_id: str) -> dict:
        state = self.get_run(run_id)
        if state["status"] in ("starting", "running"):
            (self._path("runs", run_id) / "cancel").touch()
        return {"run_id": run_id, "cancel_requested": state["status"] in ("starting", "running")}

    def get_results(self, run_id: str, case_id: str | None = None) -> dict:
        folder = self._path("runs", run_id)
        state = self.get_run(run_id)
        files = sorted((folder / "cases").glob("*.json"))
        if case_id:
            files = [p for p in files if p.stem == case_id]
            if not files:
                raise ValueError("Case not found among completed results; inspect run progress and returned case IDs.")
        return {"run": state, "cases": [read_json(p) for p in files],
                "evaluation": read_json(folder / "evaluation.json") if (folder / "evaluation.json").exists() else None}

    def compare_runs(self, run_ids: list[str]) -> dict:
        if len(run_ids) < 2 or len(run_ids) > 8:
